 if(path==="/checkout"&&$("#c-coupon")){const profile=savedProfile();$("#c-coupon").value=localStorage.getItem(couponKey)||"";if(!$("#c-name").value)$("#c-name").value=profile.name||"";if(!$("#c-phone").value)$("#c-phone").value=profile.phone||"";}
 if(path==="/cart"&&$(".summary-card .btn-primary")){const code=localStorage.getItem(couponKey)||"";$(".summary-card .btn-primary").insertAdjacentHTML("beforebegin",`<form id="cart-coupon-form"><label class="sr-only" for="cart-coupon">Promotion code</label><div class="coupon-row"><input id="cart-coupon" name="couponCode" placeholder="Promotion code" value="${esc(code)}"><button>Apply</button></div></form><p class="hint">${code?`Promotion ${esc(code)} saved; checkout will recalculate eligibility.`:"Check a preview promotion code."}</p>`);}
