async function addToCart(sku,quantity=1){const rows=cart(),row=rows.find(x=>x.sku===sku);if(row)row.quantity=Math.min(99,row.quantity+quantity);else rows.push({sku,quantity});if(!await saveCart(rows)){toast("Bag saved on this device, but could not sync to the preview server.",true);return;}toast("Added to your bag.");render();}
async function updateCart(sku,delta){const rows=cart().map(x=>x.sku===sku?{...x,quantity:x.quantity+delta}:x).filter(x=>x.quantity>0);if(!await saveCart(rows)){toast("Bag saved on this device, but could not sync to the preview server.",true);return;}render();}
