document.addEventListener("change",async e=>{
 const t=e.target;
 if(t.id==="product-image"&&t.files?.length){let rows=imageGalleryRows();if(rows.length+t.files.length>8){toast("A product can have at most 8 images.",true);t.value="";return;}try{for(const file of [...t.files]){if(file.size>4*1024*1024)throw new Error(`${file.name} exceeds the 4 MB image limit.`);const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error(`Could not read ${file.name}.`));reader.readAsDataURL(file);});const uploaded=await api("/api/v1/admin/media",{method:"POST",body:JSON.stringify({filename:file.name,data})});rows.push({url:uploaded.url,alt:""});}saveImageGallery(rows);toast("Images uploaded. Add alt text and order them before saving.");}catch(err){toast(err.message,true);}finally{t.value="";}return;}
 if(t.matches("[data-variant]")){pickedVariant=t.value;try{const p=await api(`/api/v1/products/${encodeURIComponent(location.pathname.split("/").pop())}`);const v=p.variants.find(x=>x.sku===pickedVariant);$("#detail-price").innerHTML=`${money(v.pricePaise)} ${v.mrpPaise>v.pricePaise?`<del>${money(v.mrpPaise)}</del>`:""}`;$("#detail-sku").textContent=v.sku;$("#detail-stock").textContent=v.stock>0?`${v.stock} available`:"Out of stock";$("[data-detail-add]").disabled=v.stock<1;}catch{}}
 if(t.matches("[data-sort]")){const params=new URLSearchParams(location.search);params.set("sort",t.value);params.set("page","1");location.search=params.toString();}
 if(t.id==="product-filter"||t.id==="status-filter"){const q=$("#product-filter")?.value.toLowerCase()||"",status=$("#status-filter")?.value||"";document.querySelectorAll("[data-product-row]").forEach(r=>r.hidden=!(r.dataset.search.includes(q)&&(!status||r.dataset.status===status)));}
 if(t.id==="csv-file"&&t.files?.[0]){try{rawImportRows=parseCsv(await t.files[0].text());await validateImport($("#import-mode")?.value||"create");}catch(err){rawImportRows=[];importRows=[];importErrors=[];toast(err.message,true);}}
 if(t.id==="import-mode"&&rawImportRows.length){try{await validateImport(t.value);}catch(err){toast(err.message,true);}}
});
document.addEventListener("submit",async e=>{
 const f=e.target;if(!(f instanceof HTMLFormElement))return;e.preventDefault();
 try{
  if(f.id==="cart-coupon-form"){const code=String(readForm(f).couponCode||"").trim().toUpperCase();if(!code){localStorage.removeItem(couponKey);toast("Promotion removed.");render();return;}const quote=await api("/api/v1/checkout/quote",{method:"POST",body:JSON.stringify({items:cart(),couponCode:code})});localStorage.setItem(couponKey,quote.couponCode);toast(`Promotion applied. Preview discount: ${money(quote.discountPaise)}.`);render();return;}
  if(f.id==="customer-profile-form"){await api("/api/v1/customer/profile",{method:"PATCH",body:JSON.stringify(readForm(f))});toast("Profile saved to your account.");render();return;}
  if(f.id==="delivery-check-form"){const pin=String(readForm(f).pincode||"").trim(),result=$("#delivery-check-result");result.textContent="Checking configured preview areas‚Ä¶";const data=await api(`/api/v1/serviceability/${encodeURIComponent(pin)}`);result.textContent=!data.configured?"No preview delivery areas are configured; availability is not known.":data.available?`Preview serviceable${data.area.city?` to ${data.area.city}`:""}. Fee: ${money(data.area.feePaise)}${data.area.estimate?` ¬∑ estimate ${data.area.estimate}`:""}. Confirm current delivery details with AgroSeed.`:"This PIN is not included in the configured preview delivery areas.";return;}
  if(f.id==="profile-form"){localStorage.setItem(profileKey,JSON.stringify(readForm(f)));toast("Guest profile saved on this device.");return;}
  if(f.id==="address-form"){const d=readForm(f);d.isDefault=d.isDefault==="on";if(customerSession){await api("/api/v1/customer/addresses",{method:d.id?"PUT":"POST",body:JSON.stringify(d)});toast("Address saved to your account.");route("/account/addresses");return;}const rows=addressBook(),id=d.id||`address-${Date.now()}`,isDefault=d.isDefault||!rows.length,record={...d,id,isDefault};const next=rows.filter(x=>x.id!==id).map(x=>({...x,isDefault:isDefault?false:!!x.isDefault}));next.push(record);if(!next.some(x=>x.isDefault))next[0].isDefault=true;saveAddressBook(next);toast("Address saved on this device.");route("/account/addresses");return;}
  if(f.id==="checkout-form"){
   const b=$("#quote-button");if(b.dataset.ready==="yes"){
    const a=readForm(f),rows=cart(),couponCode=String(a.couponCode||"").trim().toUpperCase();delete a.couponCode;const book=addressBook(),matched=book.find(x=>x.name===a.name&&x.phone===a.phone&&x.line1===a.line1&&x.pincode===a.pincode),savedAddress={...a,id:matched?.id||`address-${Date.now()}`,isDefault:matched?.isDefault??!book.length};const next=book.filter(x=>x.id!==savedAddress.id).map(x=>({...x,isDefault:savedAddress.isDefault?false:!!x.isDefault}));next.push(savedAddress);saveAddressBook(next);const order=await api("/api/v1/orders",{method:"POST",body:JSON.stringify({items:rows,address:a,couponCode})});saveOrderToken(order);await saveCart([]);localStorage.removeItem(couponKey);route(`/order/${encodeURIComponent(order.orderNumber)}`);return;
   }
   const a=readForm(f),quote=await api("/api/v1/checkout/quote",{method:"POST",body:JSON.stringify({items:cart(),address:a,couponCode:a.couponCode})});$("#checkout-summary").innerHTML=`<div class="checkout-lines">${quote.items.map(x=>`<div class="checkout-line"><span>${x.quantity} √ó ${esc(x.nameEn)} ¬∑ ${esc(x.pack)}</span><b>${money(x.lineTotalPaise)}</b></div>`).join("")}</div><div class="summary-row"><span>Subtotal</span><b>${money(quote.subtotalPaise)}</b></div><div class="summary-row"><span>Discount</span><b>‚àí ${money(quote.discountPaise)}</b></div><div class="summary-row"><span>Delivery ¬∑ preview estimate</span><b>${money(quote.shippingPaise)}</b></div><div class="summary-row total"><span>Preview total</span><b>${money(quote.totalPaise)}</b></div><p class="hint">${quote.serviceability==="preview_only"?"No delivery rules are configured. This is an estimate only.":"PIN code matches a configured preview area."}</p>`;b.textContent="Create sandbox preview order";b.dataset.ready="yes";return;
  }
  if(f.id==="support-form"){const d=await api("/api/v1/support/requests",{method:"POST",body:formDataJson(f)});f.innerHTML=`<div class="notice">Your message was saved in the local preview inbox. Reference: <b>${esc(d.ticket)}</b>. No email was sent.</div>`;return;}
  if(f.id==="track-form"){const d=readForm(f);saveOrderToken({orderNumber:d.orderNumber,lookupToken:d.token});route(`/order/${encodeURIComponent(d.orderNumber)}`);return;}
  if(f.id==="admin-login-form"){const d=await api("/api/v1/admin/session",{method:"POST",body:formDataJson(f)});csrf=d.csrf;route(d.user?.role==="Catalog"?"/admin/products":d.user?.role==="Orders"?"/admin/orders":"/admin");return;}
  if(f.id==="product-form"){const d=readForm(f);d.images=d.images?d.images.split(",").filter(Boolean):[];try{d.imageAlt=JSON.parse(d.imageAlt||"[]");}catch{d.imageAlt=[];}if(d.images.some((_,i)=>!String(d.imageAlt[i]||"").trim()))throw new Error("Add alt text for every product image before saving.");d.variants=parseVariants(d.variants);const id=f.dataset.id;await api(id?`/api/v1/admin/products/${id}`:"/api/v1/admin/products",{method:id?"PATCH":"POST",body:JSON.stringify(d)});toast("Product saved.");route("/admin/products");return;}
  if(f.id==="dialog-form"){await api("/api/v1/admin/inventory",{method:"POST",body:JSON.stringify({...readForm(f),sku:f.dataset.sku,delta:Number(readForm(f).delta)})});$("#dialog-root").innerHTML="";toast("Inventory adjustment saved.");render();return;}
  if(f.id==="coupon-form"){await api("/api/v1/admin/coupons",{method:"POST",body:formDataJson(f)});toast("Promotion created.");render();return;}
  if(f.id==="area-form"){await api("/api/v1/admin/service-areas",{method:"POST",body:formDataJson(f)});toast("Delivery area added.");render();return;}
  if(f.id==="settings-form"){await api("/api/v1/admin/settings",{method:"PATCH",body:formDataJson(f)});toast("Store profile saved.");return;}
  if(f.matches("[data-taxonomy-form]")){const d=readForm(f);await api(`/api/v1/admin/catalog/${f.dataset.kind}/${encodeURIComponent(f.dataset.id)}`,{method:"PATCH",body:JSON.stringify({...d,order:Number(d.order),active:d.active==="true"})});toast("Browse label updated.");render();return;}
  if(f.id==="category-form"||f.id==="brand-form"){const d=await api("/api/v1/admin/settings"),key=f.id==="category-form"?"categories":"brands",row=readForm(f);if(d[key].some(x=>x.nameEn.toLowerCase()===row.nameEn.trim().toLowerCase()))throw new Error("That browse label already exists.");d[key]=[...d[key],{id:slug(row.nameEn),name:row.name||row.nameEn,nameEn:row.nameEn,slug:slug(row.nameEn),active:true,order:d[key].length}];await api("/api/v1/admin/settings",{method:"PATCH",body:JSON.stringify(d)});toast("Browse label added.");render();return;}
 }catch(err){toast(err.message,true);}
});
document.addEventListener("click",async e=>{
 const b=e.target.closest("[data-import]");if(b){try{if(!importRows.length)return;const out=await api("/api/v1/admin/import",{method:"POST",body:JSON.stringify({rows:importRows,mode:$("#import-mode").value})});toast(`Import finished: ${out.created.length} created, ${out.updated.length} updated, ${out.errors.length} errors.`);$("#csv-preview").insertAdjacentHTML("beforeend",out.errors.length?`<div class="callout">${out.errors.map(x=>`Row ${x.row}: ${esc(x.error)}`).join("<br>")}</div>`:`<div class="notice">${out.created.length+out.updated.length} rows applied.</div>`);}catch(err){toast(err.message,true);}}
});
render();






